function Logo({ compact = false }: { compact?: boolean }) {
  return <div className="flex items-center gap-2.5" data-testid="brand-clique">
    <div className="relative grid h-9 w-9 place-items-center rounded-xl bg-accent text-accent-foreground shadow-sm"><span className="absolute h-4 w-4 rounded-full border-2 border-current opacity-80" /><span className="absolute h-1.5 w-1.5 rounded-full bg-current" /></div>
    {!compact && <div><div className="font-serif text-[17px] font-extrabold tracking-[-.04em] text-sidebar-foreground">clique<span className="text-accent">.</span></div><div className="text-[9px] font-bold uppercase tracking-[.18em] text-sidebar-foreground/55">for schools</div></div>}
  </div>;
}

function Button({ children, onClick, variant = 'primary', className = '', type = 'button', disabled = false, testId }: { children: React.ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'ghost' | 'outline'; className?: string; type?: 'button' | 'submit'; disabled?: boolean; testId?: string }) {
  const styles = { primary: 'bg-primary text-primary-foreground hover:-translate-y-0.5 hover:shadow-md', secondary: 'bg-secondary text-secondary-foreground hover:bg-muted', ghost: 'text-muted-foreground hover:bg-muted hover:text-foreground', outline: 'border border-border bg-card text-foreground hover:border-primary/40 hover:bg-secondary' };
  return <button type={type} onClick={onClick} disabled={disabled} data-testid={testId} className={`inline-flex items-center justify-center gap-2 rounded-xl px-3.5 py-2.5 text-sm font-bold disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`}>{children}</button>;
}

function Badge({ children, tone = 'blue' }: { children: React.ReactNode; tone?: 'blue' | 'coral' | 'green' | 'amber' | 'slate' }) {
  const tones = { blue: 'bg-primary/10 text-primary', coral: 'bg-accent/12 text-accent-foreground', green: 'bg-emerald-100 text-emerald-800', amber: 'bg-amber-100 text-amber-800', slate: 'bg-muted text-muted-foreground' };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold ${tones[tone]}`}>{children}</span>;
}

function Avatar({ name, size = 'md' }: { name: string; size?: 'sm' | 'md' | 'lg' }) {
  const initials = name.split(' ').map((part) => part[0]).slice(0, 2).join('');
  return <div className={`grid shrink-0 place-items-center rounded-full bg-[#d6e5ea] font-serif font-extrabold text-primary ${size === 'sm' ? 'h-7 w-7 text-[10px]' : size === 'lg' ? 'h-14 w-14 text-lg' : 'h-9 w-9 text-xs'}`} data-testid={`avatar-${name.replaceAll(' ', '-').toLowerCase()}`}>{initials}</div>;
}

function Field({ label, value, onChange, placeholder, type = 'text', testId }: { label: string; value: string; onChange: (v: string) => void; placeholder?: string; type?: string; testId: string }) {
  return <label className="grid gap-1.5 text-sm font-bold text-foreground"><span>{label}</span><input data-testid={testId} type={type} value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className="h-11 rounded-xl border border-input bg-card px-3.5 font-normal outline-none placeholder:text-muted-foreground/65 focus:border-accent focus:ring-4 focus:ring-accent/10" /></label>;
}

function LoadingState() {
  return <div className="grid gap-3"><div className="skeleton h-20 rounded-2xl" /><div className="grid gap-3 md:grid-cols-3"><div className="skeleton h-32 rounded-2xl" /><div className="skeleton h-32 rounded-2xl" /><div className="skeleton h-32 rounded-2xl" /></div><div className="skeleton h-64 rounded-2xl" /></div>;
}

function EmptyState({ title, body, action }: { title: string; body: string; action?: string }) {
  return <div className="grid place-items-center rounded-2xl border border-dashed border-border bg-card px-6 py-14 text-center"><div className="mb-3 grid h-12 w-12 place-items-center rounded-2xl bg-secondary text-primary"><Sparkles size={20} /></div><h3 className="font-serif text-xl font-extrabold">{title}</h3><p className="mt-1 max-w-sm text-sm text-muted-foreground">{body}</p>{action && <Button className="mt-5">{action}<ArrowRight size={16} /></Button>}</div>;
}

